            best_v <= 1'b1; best_m <= md; best_n <= n;
          end
          nm <= 32'($signed({2'b0, nm}) + (($signed({2'b0, 32'((33'(md) + 33'(mz)) >> 1)}) - $signed({2'b0, nm})) >>> 10));
          st <= S_DEC2;
        end

        S_DEC2: begin                                // search: dummy candidate
          if (fst == SEARCH && mz > best_m) begin
            best_m <= mz; best_n <= n;
          end
          thresh_q <= thresh;
          thr  <= (pk >> 2) > thresh ? (pk >> 2) : thresh;
          nm4  <= {nm, 2'b00};
          nm10 <= 36'(nm) * 36'd10;
          st <= S_DEC3;
        end

        S_DEC3: begin                                // next header of the best due: check it
          if (fst == SEARCH && n == best_n + LEN_Z - 32'(W)) begin
            fst <= CHECK;
            nchk <= 1'b0;
            nbad <= '0;
            chk_alt <= 1'b1;
            pred <= best_n + LEN_Z;
            win_v <= 1'b0;
          end else if (fst == SEARCH && n == best_n + len_d - 32'(W)) begin
            fst <= CHECK;
            nchk <= 1'b0;
            nbad <= '0;
            chk_alt <= 1'b0;
            pred <= best_n + len_d;
            win_v <= 1'b0;
          end
          st <= S_DEC4;
        end

        S_DEC4: begin
          inwin <= fst != SEARCH && n + 32'(W) >= pred && n <= pred + 32'(W);
          st <= S_DEC5;
        end

        S_DEC5: begin
          if (inwin && (!win_v || md > win_m)) begin
            win_v <= 1'b1; win_m <= md; win_n <= n; win_c <= 1'b0;
          end
          if (inwin && n == pred) begin
            cwin_m <= md; cwin_c <= 1'b0;
          end
          st <= S_DEC6;
        end

        S_DEC6: begin
          if (inwin && mz > win_m) begin
            win_m <= mz; win_n <= n; win_c <= 1'b1;
          end
          if (inwin && n == pred && mz > cwin_m) begin
            cwin_m <= mz; cwin_c <= 1'b1;
          end
          st <= S_DEC65;
        end

        S_DEC65: begin
          // LOCKED: stay at the predicted position unless clearly beaten
          if (inwin && n == pred + 32'(W) && fst == LOCKED && 33'(win_m) <= {cwin_m, 1'b0}) begin
            win_m <= cwin_m; win_n <= pred; win_c <= cwin_c;
          end
          st <= S_DEC7;
        end

        S_DEC7: begin
          if (inwin && n == pred + 32'(W)) begin : dec
            logic ok;
            if (fst == CHECK) begin
              if (!nchk) ok = win_m > thresh_q && 34'(win_m) > nm4;
              else       ok = win_m > thresh_q && 34'(win_m) > nm4 && 36'(csum) + 36'(win_m) > nm10;
              csum <= nchk ? csum + 33'(win_m) : 33'(win_m);
            end else ok = win_m > thr;
            if (ok) begin
              pend_v <= 1'b1; pend_hs <= win_n - 32'd89; pend_c <= win_c; pend_f <= 1'b1;
              pr_v <= 1'b0; pw_on <= 1'b1; pw_cnt <= 12'(PLS_AT);
              if (fst == LOCKED || nchk) fst <= LOCKED;
              nchk <= 1'b1;
              chk_alt <= 1'b0;
              miss <= '0;
              pk <= (pk == 0) ? win_m : 32'($signed({1'b0, pk}) + ($signed({1'b0, win_m}) - $signed({1'b0, pk})) >>> 3);
              pred <= win_n + flen(win_c, len_d);
              have_last <= 1'b1; last_n <= win_n;
              cnt_found <= cnt_found + 16'd1;
            end else if (fst == CHECK) begin
              fst <= SEARCH;
              if (!chk_alt) best_v <= 1'b0;   // else: wait for the data length
              chk_alt <= 1'b0;
              have_last <= 1'b0;
              pk <= '0;
            end else if (miss + 4'd1 > 4'(MAXMISS)) begin
              miss <= miss + 4'd1;
              fst <= SEARCH;
              best_v <= 1'b0;
              pk <= '0;
              have_last <= 1'b0;
              cnt_lost <= cnt_lost + 16'd1;
            end else begin
              miss <= miss + 4'd1;
              pend_v <= 1'b1; pend_hs <= pred - 32'd89; pend_c <= win_c; pend_f <= 1'b0;
              pr_v <= 1'b0; pw_on <= 1'b1; pw_cnt <= 12'(PLS_AT);
              pred <= pred + flen(win_c, len_d);
              have_last <= 1'b1; last_n <= pred;
              cnt_flywheel <= cnt_flywheel + 16'd1;
            end
            win_v <= 1'b0;
          end
          st <= S_OUT;
        end

        S_OUT: begin
          if (n < 32'(DELAY)) begin
            n <= n + 32'd1;
            if (pw_on && pw_cnt != '0) pw_cnt <= pw_cnt - 12'd1;
            st <= S_IN;
          end else if (!m_valid || m_ready) begin : out
            logic [31:0] o, sv;
            o  = n - 32'(DELAY);
            sv = sbuf[{cur, o[6:0]}];
            m_valid <= !cur_rst;       // (a symbol of a slot in reset is dropped)
            m_slot  <= cur;
            m_i <= $signed(sv[15:0]);
            m_q <= $signed(sv[31:16]);
            m_sof   <= pend_v && (pend_hs == o);
            m_dummy <= pend_c;
            m_found <= pend_f;
            if (pend_v && pend_hs == o) pend_v <= 1'b0;
            n <= n + 32'd1;
            if (pw_on && pw_cnt != '0) pw_cnt <= pw_cnt - 12'd1;
            st <= S_IN;
          end
        end

        default: st <= S_IN;
      endcase
    end
    if (ctx_swap) begin
      best_m <= best_m_sh;
      best_n <= best_n_sh;
      best_v <= best_v_sh;
      chk_alt <= chk_alt_sh;
      cnt_flywheel <= cnt_flywheel_sh;
      cnt_found <= cnt_found_sh;
      cnt_lost <= cnt_lost_sh;
      csum <= csum_sh;
      cwin_c <= cwin_c_sh;
      cwin_m <= cwin_m_sh;
      fst <= fst_sh;
      have_last <= have_last_sh;
      last_n <= last_n_sh;
      miss <= miss_sh;
      n <= n_sh;
      nbad <= nbad_sh;
      nchk <= nchk_sh;
      nm <= nm_sh;
      pend_c <= pend_c_sh;
      pend_f <= pend_f_sh;
      pend_hs <= pend_hs_sh;
      pend_v <= pend_v_sh;
      pi_ <= pi__sh;
      pk <= pk_sh;
      pq <= pq_sh;
      pr_dummy <= pr_dummy_sh;
      pr_ok <= pr_ok_sh;
      pr_v <= pr_v_sh;
      pred <= pred_sh;
      pw_cnt <= pw_cnt_sh;
      pw_on <= pw_on_sh;
      ty_p <= ty_p_sh;
      ty_pc <= ty_pc_sh;
      win_c <= win_c_sh;
      win_m <= win_m_sh;
      win_n <= win_n_sh;
      win_v <= win_v_sh;
      // (pulses for the slot swapped in, in this clock)
      if (ty_v2[!cur]) begin
        ty_p <= 1'b1; ty_pc <= ty_dummy;
      end
      if (pls_v2[!cur]) begin
        pr_v     <= 1'b1;
        pr_dummy <= pls_code2[!cur][6:2] == 5'd0;
        pr_ok    <= pls_conf2[!cur] && (pls_code2[!cur][6:2] == 5'd0 || pls_code2[!cur] == {modcod2[!cur], 1'b0, pilots2[!cur]});
      end
`ifdef RX2_SCRAMBLE
      Ad_i <= $bits(Ad_i)'({$urandom, $urandom});
      Ad_q <= $bits(Ad_q)'({$urandom, $urandom});
      Az_i <= $bits(Az_i)'({$urandom, $urandom});
      Az_q <= $bits(Az_q)'({$urandom, $urandom});
      ci <= $bits(ci)'({$urandom, $urandom});
      cq <= $bits(cq)'({$urandom, $urandom});
      inwin <= $bits(inwin)'({$urandom, $urandom});
      md <= $bits(md)'({$urandom, $urandom});
      mz <= $bits(mz)'({$urandom, $urandom});
      nm10 <= $bits(nm10)'({$urandom, $urandom});
      nm4 <= $bits(nm4)'({$urandom, $urandom});
      p1 <= $bits(p1)'({$urandom, $urandom});
      p2 <= $bits(p2)'({$urandom, $urandom});
      p3 <= $bits(p3)'({$urandom, $urandom});
      p4 <= $bits(p4)'({$urandom, $urandom});
      pdi <= $bits(pdi)'({$urandom, $urandom});
      pdq <= $bits(pdq)'({$urandom, $urandom});
      sqd_i <= $bits(sqd_i)'({$urandom, $urandom});
      sqd_q <= $bits(sqd_q)'({$urandom, $urandom});
      sqz_i <= $bits(sqz_i)'({$urandom, $urandom});
      sqz_q <= $bits(sqz_q)'({$urandom, $urandom});
      t <= $bits(t)'({$urandom, $urandom});
      thr <= $bits(thr)'({$urandom, $urandom});
      thresh_q <= $bits(thresh_q)'({$urandom, $urandom});
`endif
    end
  end

  // ------------------------------------------------------------ slot selection
  assign fs_state2[0] = cur ? fst_sh : fst;
  assign fs_state2[1] = cur ? fst : fst_sh;
  assign cnt_found2[0] = cur ? cnt_found_sh : cnt_found;
  assign cnt_found2[1] = cur ? cnt_found : cnt_found_sh;
  assign cnt_flywheel2[0] = cur ? cnt_flywheel_sh : cnt_flywheel;
  assign cnt_flywheel2[1] = cur ? cnt_flywheel : cnt_flywheel_sh;
  assign cnt_lost2[0] = cur ? cnt_lost_sh : cnt_lost;
  assign cnt_lost2[1] = cur ? cnt_lost : cnt_lost_sh;
  // the other slot's hold for its PLS decode (as pls_hold)
  wire hold_oth = pw_on_sh && pw_cnt_sh == '0 && pls_busy2[!cur];
  assign srs      = rst_s | rp;
  assign cur_rst  = srs[cur];
  assign rl       = rst || (st == S_IN && cur_rst);
  assign av_cur   = s_valid2[cur] && !pls_hold && !cur_rst;
  assign av_oth   = s_valid2[!cur] && !hold_oth && !rst_s[!cur];
  assign ctx_swap = !rst && st == S_IN && av_oth && (!av_cur || served);
  assign s_valid  = s_valid2[cur] && !ctx_swap && !cur_rst;
  assign s_ready2[0] = s_ready && !cur && !ctx_swap && !cur_rst;
  assign s_ready2[1] = s_ready && cur && !ctx_swap && !cur_rst;
  always_ff @(posedge clk) begin
    if (rst) begin
      cur <= 1'b0; served <= 1'b0; rp <= '0;
    end else begin
      if (ctx_swap) begin
        cur <= !cur; served <= 1'b0;
      end else if (s_valid && s_ready) served <= 1'b1;
      // a reset of the loaded slot during a symbol waits for S_IN
      if (st == S_IN) rp[cur] <= 1'b0;
      else if (rst_s[cur]) rp[cur] <= 1'b1;
    end
  end

endmodule
